import 'dart:async';
import 'dart:isolate';

class Worker {
  Worker._(this._isolate, this._fromWorker, this._toWorker);

  final Isolate _isolate;
  final ReceivePort _fromWorker;
  final SendPort _toWorker;

  static Future<Worker> start() async {
    final fromWorker = ReceivePort();
    final exited = ReceivePort();
    final ready = Completer<SendPort>();

    final isolate = await Isolate.spawn(
      _main,
      fromWorker.sendPort, // step 1: hand the child a way to reach us
      onExit: exited.sendPort,
      debugName: 'worker',
    );

    // ONE listener: the first message is the handshake, the rest are replies.
    fromWorker.listen((message) {
      if (message is SendPort) {
        ready.complete(message); // step 3
      } else {
        dispatch(message);
      }
    });

    // A child that dies during startup must not hang the caller forever.
    exited.listen((_) {
      if (!ready.isCompleted) {
        ready.completeError(StateError('worker exited during startup'));
      }
    });

    return Worker._(isolate, fromWorker, await ready.future); // step 4
  }

  void send(Object job) => _toWorker.send(job);

  void dispose() {
    _fromWorker.close(); // an open port keeps its isolate alive
    _isolate.kill();
  }
}

void _main(SendPort toParent) {
  final inbox = ReceivePort();
  toParent.send(inbox.sendPort); // must be the FIRST thing sent
  inbox.listen((job) => toParent.send(handle(job)));
}

