import 'dart:isolate';

Future<void> supervise() async {
  final results = ReceivePort();
  final errors = ReceivePort();
  final exits = ReceivePort();

  await Isolate.spawn(
    _job,
    results.sendPort,
    onError: errors.sendPort,
    onExit: exits.sendPort,
    errorsAreFatal: false, // survive one bad job, keep draining the queue
    debugName: 'importer',
  );

  errors.listen((message) {
    // Always [String, String?] — the error OBJECT is never sent.
    final pair = message as List;
    reporter.record(
      pair[0] as String,
      StackTrace.fromString(pair[1] as String? ?? ''),
    );
  });

  exits.listen((_) {
    // Fires on a normal end AND on a kill: the only reliable
    // "the worker is gone" signal. Fail everything still in flight.
    for (final pending in inFlight.values) {
      pending.completeError(StateError('worker exited'));
    }
  });
}

