void spinner(SendPort toParent) {
  toParent.send('started');
  final sw = Stopwatch()..start();
  while (sw.elapsedMilliseconds < 1500) {} // no await: this is ONE event
  toParent.send('finished');
}

Future<void> demo() async {
  final port = ReceivePort();
  final exits = ReceivePort();
  final iso = await Isolate.spawn(spinner, port.sendPort, onExit: exits.sendPort);
  await Future<void>.delayed(const Duration(milliseconds: 200));

  iso.kill(); // == priority: Isolate.beforeNextEvent
  // measured: the loop still runs to 1500 ms, still sends 'finished',
  // and onExit only fires at 1501 ms.

  iso.kill(priority: Isolate.immediate);
  // measured: gone ~1 ms later, mid-loop, nothing sent.

  await exits.first; // kill() returned long before this
}

// ✅ Cooperative cancel: the worker checks between chunks, so `finally`
// runs and half-written files get cleaned up.
void chunkedWorker(SendPort toParent) {
  final inbox = ReceivePort();
  var cancelled = false;
  toParent.send(inbox.sendPort);
  inbox.listen((m) => cancelled = cancelled || m == 'cancel');

  Future<void> run(List<Job> jobs) async {
    try {
      for (final job in jobs) {
        if (cancelled) return;
        toParent.send(job.run());
        // A microtask yield is NOT enough — port messages arrive on the
        // event queue, so `await null` would never see the cancel.
        await Future<void>.delayed(Duration.zero);
      }
    } finally {
      cleanUpTempFiles();
    }
  }
}

