// ✅ one worker, many requests, replies matched by id
class Thumbnailer {
  late final SendPort _requests;
  final _pending = <int, Completer<Uint8List>>{};
  var _nextId = 0;

  Future<void> start() async {
    final fromWorker = ReceivePort();
    await Isolate.spawn(_entry, fromWorker.sendPort, debugName: 'thumbs');
    final ready = Completer<SendPort>();
    fromWorker.listen((msg) {
      if (msg is SendPort) {
        ready.complete(msg);
        return;
      }
      final (int id, Object? err, Uint8List? bytes) =
          msg as (int, Object?, Uint8List?);
      final c = _pending.remove(id)!;
      err == null ? c.complete(bytes!) : c.completeError(err);
    });
    _requests = await ready.future;
  }

  Future<Uint8List> thumb(Uint8List src) {
    final id = _nextId++;
    final c = _pending[id] = Completer<Uint8List>();
    _requests.send((id, src));
    return c.future;
  }

  // Shut down by message, not by kill: the worker gets to clean up.
  void dispose() => _requests.send(null);
}

void _entry(SendPort toMain) {
  final requests = ReceivePort();
  toMain.send(requests.sendPort);
  final table = buildLookupTable(); // warm state: built once, reused forever
  requests.listen((msg) {
    if (msg == null) {
      requests.close();
      return;
    }
    final (int id, Uint8List src) = msg as (int, Uint8List);
    try {
      toMain.send((id, null, makeThumb(src, table)));
    } catch (e) {
      toMain.send((id, e.toString(), null)); // errors travel as data
    }
  });
}

class ThumbPool {
  ThumbPool(this.size);
  final int size;
  final _idle = <Worker>[];
  final _queue = <Job>[];
  final _cancelled = <int>{};

  // One core for the UI isolate; memory, not cores, is the real cap.
  static int suggestedSize() => (Platform.numberOfProcessors - 1).clamp(1, 4);

  Future<Uint8List> submit(int id, Uint8List src) {
    final job = Job(id, src, Completer<Uint8List>());
    _queue.insert(0, job); // LIFO: the visible row is the newest request
    if (_queue.length > 32) {
      _queue.removeLast().completer.completeError(StateError('queue full'));
    }
    _pump();
    return job.completer.future;
  }

  // Free while still queued — the cheapest cancellation there is.
  void cancel(int id) => _cancelled.add(id);

  void _pump() {
    while (_idle.isNotEmpty && _queue.isNotEmpty) {
      final job = _queue.removeAt(0);
      if (_cancelled.remove(job.id)) continue; // never dispatched at all
      final worker = _idle.removeLast();
      _guard(worker, job);
      worker.run(job).whenComplete(() {
        _idle.add(worker); // an idle worker pulls the next job itself
        _pump();
      });
    }
  }

  // No preemption inside a running job: the watchdog replaces the worker
  // rather than interrupting it.
  Future<void> _guard(Worker w, Job job) async {
    await Future<void>.delayed(const Duration(seconds: 5));
    if (job.completer.isCompleted) return;
    w.isolate.kill(priority: Isolate.immediate);
    job.completer.completeError(TimeoutException('thumbnail ${job.id}'));
    _idle.remove(w);
    _idle.add(await w.respawn());
    _pump();
  }
}

