// ✅ pay for one copy at construction, then move for free
void decodeAndTransfer(Uint8List raw, SendPort next) {
  final pixels = decode(raw);
  final moved = TransferableTypedData.fromList([pixels]); // the copy is HERE
  next.send(moved); // constant time, whatever the size
  // `pixels` is still fully readable — fromList did not neuter it.
  // Holding on to it keeps 40 MB alive; let it go out of scope.
}

