// The sender's handle dies at send time, even though it still looks fine:
void senderTrap(SendPort p) {
  final t = TransferableTypedData.fromList([Uint8List(1024)]);
  p.send(t);
  t.materialize(); // throws ArgumentError — the data is not here any more
}

// Sizing the decision: one hop needs no ceremony.
void singleHop(Uint8List bytes, SendPort p) => p.send(bytes);

