// Worker: reports progress, and looks for a cancel between chunks.
void _exportWorker(SendPort toMain) {
  final control = ReceivePort(); // a ReceivePort can't be sent —
  toMain.send(control.sendPort); // the worker makes its own and sends the port
  var cancelled = false;
  control.listen((msg) {
    if (msg == 'cancel') cancelled = true;
  });

  Future<void> run() async {
    for (var chunk = 0; chunk < 100; chunk++) {
      encodeChunk(chunk); // synchronous, ~300 ms
      toMain.send(('progress', chunk / 100));

      await Future<void>.delayed(Duration.zero); // ✅ an event-loop turn
      // await null;                             // ❌ microtask only: the
      //   'cancel' message is never delivered and the loop runs to the end
      if (cancelled) {
        removeTempFile(); // cooperative cancel still runs cleanup
        toMain.send(('cancelled', chunk));
        control.close();
        return;
      }
    }
    toMain.send(('done', null));
    control.close();
  }

  run();
}

// Caller: progress in, cancel out, ports closed on both paths.
Future<void> export() async {
  final fromWorker = ReceivePort();
  final iso = await Isolate.spawn(_exportWorker, fromWorker.sendPort,
      debugName: 'export');
  SendPort? toWorker;
  cancelButton.onPressed = () => toWorker?.send('cancel');

  await for (final msg in fromWorker) {
    if (msg is SendPort) {
      toWorker = msg;
      continue;
    }
    final (String kind, Object? value) = msg as (String, Object?);
    if (kind == 'progress') {
      setProgress(value! as double);
      continue;
    }
    break; // 'done' or 'cancelled'
  }
  fromWorker.close();
  iso.kill(); // no-op if it already exited; the safety net for a wedged loop
}

